#include <bits/stdc++.h>
using namespace std;

// Stos z minimum: każdy element pamięta minimum stosu od dna do siebie.
struct MinStack {
    vector<pair<long long, long long>> s;   // (wartość, minimum do tego miejsca)
    void push(long long x) { s.push_back({x, s.empty() ? x : min(x, s.back().second)}); }
    void pop() { s.pop_back(); }
    long long top() const { return s.back().first; }
    long long getMin() const { return s.back().second; }
    bool empty() const { return s.empty(); }
    size_t size() const { return s.size(); }
};

// Kolejka FIFO z minimum na dwóch stosach: push na `in`, pop i front z `out`.
struct MinQueue {
    MinStack in, out;
    void push(long long x) { in.push(x); }
    void moveIfNeeded() {                    // przelanie odwraca kolejność: najstarszy ląduje na górze `out`
        if (out.empty())
            while (!in.empty()) { out.push(in.top()); in.pop(); }
    }
    void pop() { moveIfNeeded(); out.pop(); }
    long long front() { moveIfNeeded(); return out.top(); }
    long long getMin() const {
        if (in.empty()) return out.getMin();
        if (out.empty()) return in.getMin();
        return min(in.getMin(), out.getMin());
    }
    bool empty() const { return in.empty() && out.empty(); }
    size_t size() const { return in.size() + out.size(); }
};

int main() {
    // Wejście: q, potem q operacji: "+ x" (dodaj na koniec), "-" (usuń z początku), "?" (minimum kolejki)
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int q;
    cin >> q;
    MinQueue mq;
    while (q--) {
        char op;
        cin >> op;
        if (op == '+') {
            long long x;
            cin >> x;
            mq.push(x);
        } else if (op == '-') {
            if (!mq.empty()) mq.pop();
        } else {
            cout << (mq.empty() ? -1 : mq.getMin()) << '\n';
        }
    }
}

// Najkrótszy spójny fragment o NWD równym 1 (dwa wskaźniki + „kolejka NWD” na dwóch stosach).
// Zwraca -1, gdy taki fragment nie istnieje. Każdy element wchodzi i wychodzi raz: O(n log A).
int shortestGcdOne(const vector<long long>& a) {
    vector<long long> inV, inG, outG;            // wartości i NWD „od dna do tego miejsca”
    auto top = [](const vector<long long>& g) { return g.empty() ? 0LL : g.back(); };
    int best = INT_MAX, l = 0;
    for (int r = 0; r < (int)a.size(); r++) {
        inV.push_back(a[r]);
        inG.push_back(gcd(top(inG), a[r]));
        while (gcd(top(inG), top(outG)) == 1) {  // okno [l, r] ma NWD 1 → próbuj skrócić z lewej
            best = min(best, r - l + 1);
            if (outG.empty())                    // przelej: najstarszy element na górę outG
                while (!inV.empty()) {
                    outG.push_back(gcd(top(outG), inV.back()));
                    inV.pop_back();
                    inG.pop_back();
                }
            outG.pop_back();                     // usuń a[l]
            l++;
        }
    }
    return best == INT_MAX ? -1 : best;
}

