struct TwoStackQueue {
    stack<int> in, out;
    void push(int x) { in.push(x); }
    void shift() {                       // przelej tylko, gdy out jest pusty
        if (out.empty())
            while (!in.empty()) { out.push(in.top()); in.pop(); }
    }
    int front() { shift(); return out.top(); }
    void pop() { shift(); out.pop(); }
    bool empty() const { return in.empty() && out.empty(); }
    size_t size() const { return in.size() + out.size(); }
};

struct MinQueue {
    vector<pair<long long, long long>> in, out;   // (wartość, minimum stosu do tego miejsca)
    static void put(vector<pair<long long, long long>>& s, long long x) {
        s.push_back({x, s.empty() ? x : min(x, s.back().second)});
    }
    void push(long long x) { put(in, x); }
    void pop() {                                  // zakłada niepustą kolejkę
        if (out.empty())
            while (!in.empty()) { put(out, in.back().first); in.pop_back(); }   // minima liczone od nowa
        out.pop_back();
    }
    long long getMin() const {                    // LLONG_MAX dla pustej kolejki
        long long m = LLONG_MAX;
        if (!in.empty()) m = min(m, in.back().second);
        if (!out.empty()) m = min(m, out.back().second);
        return m;
    }
};

