#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1'000'005;
int nxt[MAXN], prv[MAXN];       // NIE nazywaj ich next/prev — kolizja z std::next/std::prev
bool gone[MAXN];

void removeNode(int x) {        // O(1); x nie może być strażnikiem
    nxt[prv[x]] = nxt[x];
    prv[nxt[x]] = prv[x];
    gone[x] = true;             // prv[x] i nxt[x] zostają — przydają się do cofania
}

void insertAfter(int x, int y) { // wstaw węzeł y tuż za x, O(1)
    prv[y] = x;
    nxt[y] = nxt[x];
    prv[nxt[x]] = y;
    nxt[x] = y;
    gone[y] = false;
}

int main() {
    // Wejście: n q, ciąg a[1..n], potem q pozycji x (oryginalne indeksy) do usunięcia.
    // Po każdym usunięciu wypisz obecnych sąsiadów (lub -1, gdy brak).
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<long long> a(n + 2, -1);              // a[0] i a[n+1] = strażnicy (wartość -1)
    for (int i = 1; i <= n; i++) cin >> a[i];
    for (int i = 0; i <= n + 1; i++) {
        prv[i] = i - 1;
        nxt[i] = i + 1;
    }
    while (q--) {
        int x;
        cin >> x;
        if (gone[x]) { cout << "juz usuniety\n"; continue; }
        removeNode(x);
        cout << a[prv[x]] << ' ' << a[nxt[x]] << '\n';
    }
    for (int i = nxt[0]; i != n + 1; i = nxt[i]) cout << a[i] << ' ';   // co zostało
    cout << '\n';
}

// res[i] = min |a[i] - a[j]| po j < i (res[0] = LLONG_MAX). Sortowanie + lista na tablicach: O(n log n).
// Idziemy od końca i usuwamy: gdy rozpatrujemy i, w liście są tylko indeksy ≤ i,
// więc sąsiedzi i w porządku wartości to najbliższe wartości spośród wcześniejszych elementów.
vector<long long> nearestBefore(const vector<long long>& a) {
    int n = a.size();
    vector<int> ord(n), pos(n), L(n), R(n);
    iota(ord.begin(), ord.end(), 0);
    sort(ord.begin(), ord.end(), [&](int x, int y) { return a[x] < a[y]; });
    for (int p = 0; p < n; p++) {
        pos[ord[p]] = p;
        L[p] = p - 1;                        // -1 = brak sąsiada
        R[p] = p + 1;                        // n  = brak sąsiada
    }
    vector<long long> res(n, LLONG_MAX);
    for (int i = n - 1; i >= 0; i--) {
        int p = pos[i];
        if (L[p] >= 0) res[i] = min(res[i], a[i] - a[ord[L[p]]]);
        if (R[p] < n) res[i] = min(res[i], a[ord[R[p]]] - a[i]);
        if (L[p] >= 0) R[L[p]] = R[p];       // usuń p z listy
        if (R[p] < n) L[R[p]] = L[p];
    }
    return res;
}

// Kolejność eliminacji w problemie Józefa Flawiusza (odliczamy co k-tą osobę), lista cykliczna.
// O(n·k) — dobre dla małego k; dla dużego k użyj Fenwicka z k-tym elementem (O(n log n)).
vector<int> josephus(int n, int k) {
    vector<int> nx(n), pv(n);
    for (int i = 0; i < n; i++) {
        nx[i] = (i + 1) % n;
        pv[i] = (i + n - 1) % n;
    }
    vector<int> order;
    int cur = n - 1;                         // stoimy tuż „przed” osobą 0
    for (int left = n; left > 0; left--) {
        int steps = (k - 1) % left + 1;      // nie kręć się w kółko bez potrzeby
        for (int s = 0; s < steps; s++) cur = nx[cur];
        order.push_back(cur + 1);            // numeracja osób od 1
        nx[pv[cur]] = nx[cur];
        pv[nx[cur]] = pv[cur];
        cur = pv[cur];
    }
    return order;                            // n = 7, k = 3 → 3 6 2 7 5 1 4
}

// Lista jednokierunkowa na tablicach = lista sąsiedztwa „forward star” (bez vectorów).
const int MAXV = 200'005, MAXE = 400'005;
int head[MAXV], nxtE[MAXE], to[MAXE], edgeCnt = 0;

void addEdge(int u, int v) {          // wstawienie na początek listy u: O(1)
    to[edgeCnt] = v;
    nxtE[edgeCnt] = head[u];
    head[u] = edgeCnt++;
}

void example(int n) {
    fill(head, head + n, -1);         // -1 = koniec listy; ustaw PRZED dodawaniem krawędzi
    addEdge(0, 1);
    addEdge(0, 2);
    for (int e = head[0]; e != -1; e = nxtE[e])
        cout << to[e] << ' ';         // 2 1 (odwrotna kolejność dodania)
    cout << '\n';
}

