#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n, LOG;
    vector<long long> t;
    Fenwick(int n) : n(n), LOG(n > 0 ? __lg(n) : 0), t(n + 1, 0) {}
    void add(int i, long long d) {           // i ∈ [1, n]
        for (; i <= n; i += i & -i) t[i] += d;
    }
    long long sum(int i) const {             // a[1] + ... + a[i]
        long long s = 0;
        for (; i > 0; i -= i & -i) s += t[i];
        return s;
    }
    // Najmniejsze p, że sum(p) >= k (wymaga a[i] >= 0). Zwraca n + 1, gdy sum(n) < k.
    int lowerBound(long long k) const {
        int pos = 0;
        for (int pw = 1 << LOG; pw > 0; pw >>= 1)
            if (pos + pw <= n && t[pos + pw] < k) {
                pos += pw;                   // cały blok (pos, pos+pw] ma sumę < k → przeskocz go
                k -= t[pos];
            }
        return pos + 1;
    }
};

int main() {
    // Multizbiór liczb z zakresu [1, 10^6]. Operacje:
    // "+ x" dodaj x, "- x" usuń jedną kopię x, "k i" i-ty najmniejszy, "c x" ile elementów < x
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    const int MAXV = 1'000'000;
    Fenwick f(MAXV);
    vector<int> cnt(MAXV + 1, 0);
    long long total = 0;
    int q;
    cin >> q;
    while (q--) {
        char op;
        long long x;
        cin >> op >> x;
        if (op == '+') { f.add(x, 1); cnt[x]++; total++; }
        else if (op == '-') { if (cnt[x] > 0) { f.add(x, -1); cnt[x]--; total--; } }
        else if (op == 'k') cout << (1 <= x && x <= total ? f.lowerBound(x) : -1) << '\n';
        else cout << f.sum(x - 1) << '\n';
    }
}

struct Fenwick {
    int n;
    vector<int> t;
    Fenwick(int n) : n(n), t(n + 1, 0) {}
    void add(int i, int d) { for (; i <= n; i += i & -i) t[i] += d; }
    int kth(int k) const {                   // najmniejsze p z sumą prefiksu >= k
        int pos = 0;
        for (int pw = 1 << __lg(n); pw > 0; pw >>= 1)
            if (pos + pw <= n && t[pos + pw] < k) { pos += pw; k -= t[pos]; }
        return pos + 1;
    }
};

// Józef Flawiusz w O(n log n): kto odpada jako kolejny, gdy odliczamy co k-tą osobę.
vector<int> josephusFast(int n, int k) {
    Fenwick f(n);
    for (int i = 1; i <= n; i++) f.add(i, 1);    // 1 = osoba jeszcze w kółku
    vector<int> order;
    int idx = 0;                                 // pozycja (od 0) w bieżącym kółku
    for (int left = n; left > 0; left--) {
        idx = (idx + k - 1) % left;
        int p = f.kth(idx + 1);                  // (idx+1)-ta żywa osoba
        order.push_back(p);
        f.add(p, -1);
    }
    return order;                                // n = 7, k = 3 → 3 6 2 7 5 1 4
}

struct Fenwick {
    int n;
    vector<int> t;
    Fenwick(int n) : n(n), t(n + 1, 0) {}
    void add(int i, int d) { for (; i <= n; i += i & -i) t[i] += d; }
    int kth(int k) const {                   // najmniejsze p z sumą prefiksu >= k
        int pos = 0;
        for (int pw = 1 << __lg(n); pw > 0; pw >>= 1)
            if (pos + pw <= n && t[pos + pw] < k) { pos += pw; k -= t[pos]; }
        return pos + 1;
    }
};

// c[i] = ile elementów PRZED pozycją i jest większych od p[i] (tablica inwersji, i od 0).
// Odtwarzamy permutację 1..n od końca: p[i] to (i + 1 - c[i])-ta najmniejsza z niewykorzystanych.
vector<int> restorePermutation(const vector<int>& c) {
    int n = c.size();
    Fenwick f(n);
    for (int v = 1; v <= n; v++) f.add(v, 1);
    vector<int> p(n);
    for (int i = n - 1; i >= 0; i--) {
        p[i] = f.kth(i + 1 - c[i]);
        f.add(p[i], -1);
    }
    return p;
}

