// c[i] = ile elementów PRZED pozycją i jest większych od p[i] (tablica inwersji, i od 0).
// Odtwarzamy permutację 1..n od końca: p[i] to (i + 1 - c[i])-ta najmniejsza z niewykorzystanych.
vector<int> restorePermutation(const vector<int>& c) {
    int n = c.size();
    Fenwick f(n);
    for (int v = 1; v <= n; v++) f.add(v, 1);
    vector<int> p(n);
    for (int i = n - 1; i >= 0; i--) {
        p[i] = f.kth(i + 1 - c[i]);
        f.add(p[i], -1);
    }
    return p;
}

