// Drzewo maksimum z zejściem: „pierwszy indeks i ≥ from, że a[i] ≥ x” w O(log n).
struct MaxTree {
    int n;
    vector<long long> t;
    MaxTree(const vector<long long>& a) : n(a.size()), t(4 * a.size()) { build(1, 0, n - 1, a); }
    void build(int v, int l, int r, const vector<long long>& a) {
        if (l == r) { t[v] = a[l]; return; }
        int m = (l + r) / 2;
        build(2 * v, l, m, a);
        build(2 * v + 1, m + 1, r, a);
        t[v] = max(t[2 * v], t[2 * v + 1]);
    }
    void add(int v, int l, int r, int pos, long long d) {
        if (l == r) { t[v] += d; return; }
        int m = (l + r) / 2;
        if (pos <= m) add(2 * v, l, m, pos, d);
        else add(2 * v + 1, m + 1, r, pos, d);
        t[v] = max(t[2 * v], t[2 * v + 1]);
    }
    int first(int v, int l, int r, int from, long long x) {
        if (r < from || t[v] < x) return -1;     // poza zakresem albo nikt tu nie ma ≥ x
        if (l == r) return l;
        int m = (l + r) / 2;
        int res = first(2 * v, l, m, from, x);   // najpierw lewy syn — szukamy NAJMNIEJSZEGO indeksu
        if (res == -1) res = first(2 * v + 1, m + 1, r, from, x);
        return res;
    }
    void add(int pos, long long d) { add(1, 0, n - 1, pos, d); }
    int first(int from, long long x) { return first(1, 0, n - 1, from, x); }
};

