// Drzewo sum (a[i] ≥ 0) z zejściem od korzenia: bez wyszukiwania binarnego, O(log n).
struct SumTree {
    int n;
    vector<long long> t;
    SumTree(int n) : n(n), t(4 * n, 0) {}
    void add(int v, int l, int r, int pos, long long d) {
        if (l == r) { t[v] += d; return; }
        int m = (l + r) / 2;
        if (pos <= m) add(2 * v, l, m, pos, d);
        else add(2 * v + 1, m + 1, r, pos, d);
        t[v] = t[2 * v] + t[2 * v + 1];
    }
    void add(int pos, long long d) { add(1, 0, n - 1, pos, d); }
    // najmniejszy indeks i, że a[0] + ... + a[i] >= s; -1, gdy suma wszystkiego < s
    int lowerBoundPrefix(long long s) const {
        if (t[1] < s) return -1;
        int v = 1, l = 0, r = n - 1;
        while (l != r) {
            int m = (l + r) / 2;
            if (t[2 * v] >= s) { v = 2 * v; r = m; }             // wystarczy lewa połowa
            else { s -= t[2 * v]; v = 2 * v + 1; l = m + 1; }   // weź całą lewą, szukaj w prawej
        }
        return l;
    }
    // indeks k-tej jedynki (k od 1) w tablicy zer i jedynek
    int kthOne(int k) const { return lowerBoundPrefix(k); }
};

// Pierwszy indeks w [ql, qr] z a[i] >= x w drzewie MAKSIMUM t[] (wywołanie: firstIn(t, 1, 0, n-1, ql, qr, x)).
int firstIn(const vector<long long>& t, int v, int l, int r, int ql, int qr, long long x) {
    if (r < ql || qr < l || t[v] < x) return -1;
    if (l == r) return l;
    int m = (l + r) / 2;
    int res = firstIn(t, 2 * v, l, m, ql, qr, x);
    if (res == -1) res = firstIn(t, 2 * v + 1, m + 1, r, ql, qr, x);
    return res;
}

