    void pop() { clean(); q.pop(); }
    size_t size() const { return q.size() - del.size(); }
    bool empty() const { return size() == 0; }
};

priority_queue<int> q, del;
for (int x : {5, 9, 7}) q.push(x);
del.push(9);                                          // „usuń 9”
while (!del.empty() && q.top() == del.top()) { q.pop(); del.pop(); }
cout << q.top() << '\n';                              // 7

vector<long long> dijkstra(const vector<vector<pair<int, long long>>>& g, int s) {
    vector<long long> dist(g.size(), LLONG_MAX);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> pq;
    dist[s] = 0;
    pq.push({0, s});
    while (!pq.empty()) {
        auto [d, v] = pq.top();
        pq.pop();
        if (d != dist[v]) continue;                   // martwy (nieaktualny) wpis — leniwe usuwanie
        for (auto [u, w] : g[v])
            if (d + w < dist[u]) {
                dist[u] = d + w;
                pq.push({dist[u], u});                // zamiast decrease-key: nowy wpis
            }
    }
    return dist;
}

// Zmiana priorytetu bez decrease-key: wrzucamy nową parę, a stare wpisy pomijamy przy zdejmowaniu.
int n = 5;
vector<int> cur(n, 0);                          // aktualny priorytet zadania id
priority_queue<pair<int, int>> pq;              // (priorytet, id)
auto setPriority = [&](int id, int p) { cur[id] = p; pq.push({p, id}); };
auto popBest = [&]() -> int {                   // zwraca id o największym priorytecie albo -1
    while (!pq.empty()) {
        auto [p, id] = pq.top();
        pq.pop();
        if (p == cur[id]) { cur[id] = INT_MIN; return id; }   // wpis aktualny → wydajemy zadanie
    }                                                       // nieaktualny → leniwie wyrzucony
    return -1;
};
setPriority(1, 10);
setPriority(2, 7);
setPriority(1, 3);                              // stary wpis (10, 1) zostaje w kopcu, ale jest martwy
cout << popBest() << ' ' << popBest() << '\n';  // 2 1

// Kopiec z usuwaniem dowolnego elementu: drugi kopiec `del` trzyma „do usunięcia”.
// Niezmiennik: del ⊆ q (jako multizbiory). Każdy element wchodzi i wychodzi ≤ 2 razy → O(log n) zamortyzowane.
template <class T, class Cmp = less<T>>
struct ErasableHeap {
    priority_queue<T, vector<T>, Cmp> q, del;
    void push(const T& x) { q.push(x); }
    void erase(const T& x) { del.push(x); }          // x MUSI być teraz w kopcu!
    void clean() {
        while (!del.empty() && q.top() == del.top()) { q.pop(); del.pop(); }
    }
    const T& top() { clean(); return q.top(); }
    void pop() { clean(); q.pop(); }
    size_t size() const { return q.size() - del.size(); }
    bool empty() const { return size() == 0; }
};

// Mediana (dolna) każdego okna długości k na dwóch kopcach z leniwym usuwaniem: O(n log n).
vector<long long> slidingMedian(const vector<long long>& a, int k) {
    ErasableHeap<long long> lo;                       // dolna połowa, maksimum na górze
    ErasableHeap<long long, greater<long long>> hi;   // górna połowa, minimum na górze
    vector<long long> res;
    for (int i = 0; i < (int)a.size(); i++) {
        if (lo.empty() || a[i] <= lo.top()) lo.push(a[i]);
        else hi.push(a[i]);
        if (i >= k) {                                 // a[i-k] wypada z okna
            if (a[i - k] <= lo.top()) lo.erase(a[i - k]);
            else hi.erase(a[i - k]);
        }
        while (lo.size() > hi.size() + 1) { hi.push(lo.top()); lo.pop(); }
        while (lo.size() < hi.size()) { lo.push(hi.top()); hi.pop(); }
        if (i >= k - 1) res.push_back(lo.top());
    }
    return res;
}

