// Drzewo kartezjańskie (kopiec MINIMUM, przy remisie korzeniem jest wcześniejszy indeks).
// L[i], R[i] = lewy/prawy syn, par[i] = ojciec (-1 = brak). Zwraca korzeń. O(n) — stos.
int buildCartesian(const vector<long long>& a, vector<int>& L, vector<int>& R, vector<int>& par) {
    int n = a.size();
    L.assign(n, -1);
    R.assign(n, -1);
    par.assign(n, -1);
    vector<int> st;                    // prawa krawędź drzewa: wartości niemalejące od dna
    for (int i = 0; i < n; i++) {
        int last = -1;
        while (!st.empty() && a[st.back()] > a[i]) { last = st.back(); st.pop_back(); }
        if (last != -1) { L[i] = last; par[last] = i; }   // zdjęty fragment → lewe poddrzewo i
        if (!st.empty()) { R[st.back()] = i; par[i] = st.back(); }
        st.push_back(i);
    }
    return st.empty() ? -1 : st[0];
}

