int main() {
    // Wejście: n, a[0..n-1]. Wypisuje: korzeń, ojców, największy prostokąt w histogramie
    // i sumę minimów wszystkich spójnych fragmentów.
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> a(n);
    for (auto& x : a) cin >> x;
    vector<int> L, R, par;
    int root = buildCartesian(a, L, R, par);

    // rozmiary poddrzew bez rekurencji: kolejność DFS, potem od końca
    vector<int> order, sz(n, 1), st = {root};
    while (!st.empty()) {
        int v = st.back();
        st.pop_back();
        order.push_back(v);
        if (L[v] != -1) st.push_back(L[v]);
        if (R[v] != -1) st.push_back(R[v]);
    }
    for (int j = n - 1; j > 0; j--) sz[par[order[j]]] += sz[order[j]];

    long long bestRect = 0, sumMin = 0;
    for (int i = 0; i < n; i++) {
        long long left = L[i] == -1 ? 0 : sz[L[i]];   // poddrzewo i = przedział [i-left, i+right],
        long long right = R[i] == -1 ? 0 : sz[R[i]];  // na którym a[i] jest minimum
        bestRect = max(bestRect, a[i] * sz[i]);
        sumMin += a[i] * (left + 1) * (right + 1);    // fragmenty z minimum (LCA) w i
    }
    cout << "korzen: " << root << "\nojcowie:";
    for (int i = 0; i < n; i++) cout << ' ' << par[i];
    cout << "\nprostokat: " << bestRect << "\nsuma minimow: " << sumMin << '\n';
}

// „Dziel po minimum” bez O(n^2): rekurencja po drzewie kartezjańskim (zamiast szukać minimum pętlą).
// Przykład: liczba fragmentów [l, r], w których min * długość >= K. Każdy węzeł v obsługuje
// fragmenty o minimum w v, czyli l ∈ [lo, v], r ∈ [v, hi]. Stos jawny → brak przepełnienia stosu.
long long countGood(const vector<long long>& a, long long K) {
    int n = a.size();
    if (n == 0) return 0;
    vector<int> L(n, -1), R(n, -1), st;
    for (int i = 0; i < n; i++) {
        int last = -1;
        while (!st.empty() && a[st.back()] > a[i]) { last = st.back(); st.pop_back(); }
        L[i] = last;
        if (!st.empty()) R[st.back()] = i;
        st.push_back(i);
    }
    long long res = 0;
    vector<array<int, 3>> todo = {{st[0], 0, n - 1}};      // (węzeł, lo, hi)
    while (!todo.empty()) {
        auto [v, lo, hi] = todo.back();
        todo.pop_back();
        // fragmenty l ∈ [lo, v], r ∈ [v, hi]: przechodzimy po MNIEJSZEJ stronie (small-to-large → O(n log n))
        long long need = K <= 0 ? 1 : (a[v] > 0 ? (K + a[v] - 1) / a[v] : n + 1);   // min. długość
        if (v - lo <= hi - v) {
            for (int l = lo; l <= v; l++) {
                long long rmin = max<long long>(v, l + need - 1);
                if (rmin <= hi) res += hi - rmin + 1;
            }
        } else {
            for (int r = v; r <= hi; r++) {
                long long lmax = min<long long>(v, r - need + 1);
                if (lmax >= lo) res += lmax - lo + 1;
            }
        }
        if (L[v] != -1) todo.push_back({L[v], lo, v - 1});
        if (R[v] != -1) todo.push_back({R[v], v + 1, hi});
    }
    return res;
}

// Poddrzewo i w drzewie kartezjańskim = przedział [lo[i], hi[i]], na którym a[i] jest minimum:
// lo = za najbliższym na lewo ≤ a[i], hi = przed najbliższym na prawo < a[i]. Liczone tym samym stosem.
void subtreeRanges(const vector<long long>& a, vector<int>& lo, vector<int>& hi) {
    int n = a.size();
    lo.assign(n, 0);
    hi.assign(n, n - 1);
    vector<int> st;
    for (int i = 0; i < n; i++) {
        while (!st.empty() && a[st.back()] > a[i]) { hi[st.back()] = i - 1; st.pop_back(); }
        lo[i] = st.empty() ? 0 : st.back() + 1;
        st.push_back(i);
    }
}

long long largestRectangle(const vector<long long>& h) {      // największy prostokąt w histogramie
    vector<int> lo, hi;
    subtreeRanges(h, lo, hi);
    long long best = 0;
    for (int i = 0; i < (int)h.size(); i++) best = max(best, h[i] * (hi[i] - lo[i] + 1));
    return best;
}

long long sumOfMinima(const vector<long long>& a) {           // suma min po wszystkich fragmentach
    vector<int> lo, hi;
    subtreeRanges(a, lo, hi);
    long long s = 0;
    for (int i = 0; i < (int)a.size(); i++) s += a[i] * (i - lo[i] + 1) * (hi[i] - i + 1);
    return s;
}

// Treap z POSORTOWANYCH kluczy w O(n): to drzewo kartezjańskie po priorytetach (kopiec maksimum).
struct Node { int key, pri, l = -1, r = -1; };

int buildTreapSorted(vector<Node>& t) {          // t posortowane rosnąco po key
    vector<int> st;
    for (int i = 0; i < (int)t.size(); i++) {
        int last = -1;
        while (!st.empty() && t[st.back()].pri < t[i].pri) { last = st.back(); st.pop_back(); }
        t[i].l = last;
        if (!st.empty()) t[st.back()].r = i;
        st.push_back(i);
    }
    return st.empty() ? -1 : st[0];              // korzeń
}

