#include <bits/stdc++.h>
using namespace std;

// Segment tree beats (Ji): a[i] = min(a[i], x) na przedziale + suma i maksimum na przedziale.
// Węzeł: mx = maksimum, se = ŚCIŚLE drugie maksimum, cnt = ile razy występuje mx, sum = suma.
const long long NEG = LLONG_MIN / 4;
int n;
vector<long long> mx, se, sum;
vector<int> cnt;

void pull(int v) {
    int a = 2 * v, b = 2 * v + 1;
    sum[v] = sum[a] + sum[b];
    if (mx[a] == mx[b]) { mx[v] = mx[a]; cnt[v] = cnt[a] + cnt[b]; se[v] = max(se[a], se[b]); }
    else if (mx[a] > mx[b]) { mx[v] = mx[a]; cnt[v] = cnt[a]; se[v] = max(se[a], mx[b]); }
    else { mx[v] = mx[b]; cnt[v] = cnt[b]; se[v] = max(mx[a], se[b]); }
}

void applyMin(int v, long long x) {      // wymaga se[v] < x: zmieniają się tylko maksima węzła
    if (mx[v] <= x) return;
    sum[v] -= (mx[v] - x) * cnt[v];
    mx[v] = x;
}

void push(int v) {                        // „lazy” = maksimum ojca: syn nie może go przekraczać
    applyMin(2 * v, mx[v]);
    applyMin(2 * v + 1, mx[v]);
}

void build(int v, int l, int r, const vector<long long>& a) {
    if (l == r) { mx[v] = sum[v] = a[l]; se[v] = NEG; cnt[v] = 1; return; }
    int m = (l + r) / 2;
    build(2 * v, l, m, a);
    build(2 * v + 1, m + 1, r, a);
    pull(v);
}

void chmin(int v, int l, int r, int ql, int qr, long long x) {
    if (qr < l || r < ql || mx[v] <= x) return;              // break: nic do zmiany
    if (ql <= l && r <= qr && se[v] < x) { applyMin(v, x); return; }   // tag: zmieniamy tylko mx
    push(v);
    int m = (l + r) / 2;
    chmin(2 * v, l, m, ql, qr, x);
    chmin(2 * v + 1, m + 1, r, ql, qr, x);
    pull(v);
}

long long qsum(int v, int l, int r, int ql, int qr) {
    if (qr < l || r < ql) return 0;
    if (ql <= l && r <= qr) return sum[v];
    push(v);
    int m = (l + r) / 2;
    return qsum(2 * v, l, m, ql, qr) + qsum(2 * v + 1, m + 1, r, ql, qr);
}

long long qmax(int v, int l, int r, int ql, int qr) {
    if (qr < l || r < ql) return NEG;
    if (ql <= l && r <= qr) return mx[v];
    push(v);
    int m = (l + r) / 2;
