// Pełne beats: chmin, chmax, add na przedziale + suma/max/min. O((n + q) log² n) zamortyzowane.
struct Beats {
    static constexpr long long INF = LLONG_MAX / 4;
    int n;
    vector<long long> sum, mx1, mx2, mn1, mn2, lz;   // mx2/mn2 = ŚCIŚLE drugie max/min
    vector<int> cmx, cmn, len;
    Beats(const vector<long long>& a) : n(a.size()) {
        int s = 4 * n;
        sum.assign(s, 0); mx1 = mx2 = mn1 = mn2 = lz = sum;
        cmx.assign(s, 0); cmn = len = cmx;
        build(1, 0, n - 1, a);
    }
    void pull(int v) {
        int a = 2 * v, b = 2 * v + 1;
        sum[v] = sum[a] + sum[b];
        if (mx1[a] == mx1[b]) { mx1[v] = mx1[a]; cmx[v] = cmx[a] + cmx[b]; mx2[v] = max(mx2[a], mx2[b]); }
        else if (mx1[a] > mx1[b]) { mx1[v] = mx1[a]; cmx[v] = cmx[a]; mx2[v] = max(mx2[a], mx1[b]); }
        else { mx1[v] = mx1[b]; cmx[v] = cmx[b]; mx2[v] = max(mx1[a], mx2[b]); }
        if (mn1[a] == mn1[b]) { mn1[v] = mn1[a]; cmn[v] = cmn[a] + cmn[b]; mn2[v] = min(mn2[a], mn2[b]); }
        else if (mn1[a] < mn1[b]) { mn1[v] = mn1[a]; cmn[v] = cmn[a]; mn2[v] = min(mn2[a], mn1[b]); }
        else { mn1[v] = mn1[b]; cmn[v] = cmn[b]; mn2[v] = min(mn1[a], mn2[b]); }
    }
    void build(int v, int l, int r, const vector<long long>& a) {
        len[v] = r - l + 1;
        if (l == r) {
            sum[v] = mx1[v] = mn1[v] = a[l];
            mx2[v] = -INF; mn2[v] = INF; cmx[v] = cmn[v] = 1;
            return;
        }
        int m = (l + r) / 2;
        build(2 * v, l, m, a);
        build(2 * v + 1, m + 1, r, a);
        pull(v);
    }
    void applyAdd(int v, long long x) {
        sum[v] += x * len[v];
        mx1[v] += x; if (mx2[v] != -INF) mx2[v] += x;
        mn1[v] += x; if (mn2[v] != INF) mn2[v] += x;
        lz[v] += x;
    }
    void applyChmin(int v, long long x) {        // wymaga mx2[v] < x
        if (mx1[v] <= x) return;
        sum[v] -= (mx1[v] - x) * cmx[v];
        if (mn1[v] == mx1[v]) mn1[v] = x;        // węzeł miał jedną wartość
        else if (mn2[v] == mx1[v]) mn2[v] = x;   // dwie wartości: stare max było drugim min
        mx1[v] = x;
    }
    void applyChmax(int v, long long x) {        // wymaga mn2[v] > x
        if (mn1[v] >= x) return;
        sum[v] += (x - mn1[v]) * cmn[v];
        if (mx1[v] == mn1[v]) mx1[v] = x;
        else if (mx2[v] == mn1[v]) mx2[v] = x;
        mn1[v] = x;
    }
    void push(int v) {                           // kolejność: add, potem obcięcie do max/min ojca
        for (int c : {2 * v, 2 * v + 1}) {
            if (lz[v]) applyAdd(c, lz[v]);
            applyChmin(c, mx1[v]);
            applyChmax(c, mn1[v]);
        }
        lz[v] = 0;
    }
    void chmin(int v, int l, int r, int ql, int qr, long long x) {
        if (qr < l || r < ql || mx1[v] <= x) return;
        if (ql <= l && r <= qr && mx2[v] < x) { applyChmin(v, x); return; }
        push(v);
        int m = (l + r) / 2;
        chmin(2 * v, l, m, ql, qr, x); chmin(2 * v + 1, m + 1, r, ql, qr, x);
        pull(v);
    }
    void chmax(int v, int l, int r, int ql, int qr, long long x) {
        if (qr < l || r < ql || mn1[v] >= x) return;
        if (ql <= l && r <= qr && mn2[v] > x) { applyChmax(v, x); return; }
        push(v);
        int m = (l + r) / 2;
        chmax(2 * v, l, m, ql, qr, x); chmax(2 * v + 1, m + 1, r, ql, qr, x);
        pull(v);
    }
    void add(int v, int l, int r, int ql, int qr, long long x) {
        if (qr < l || r < ql) return;
        if (ql <= l && r <= qr) { applyAdd(v, x); return; }
        push(v);
        int m = (l + r) / 2;
        add(2 * v, l, m, ql, qr, x); add(2 * v + 1, m + 1, r, ql, qr, x);
        pull(v);
    }
    long long qsum(int v, int l, int r, int ql, int qr) {
        if (qr < l || r < ql) return 0;
        if (ql <= l && r <= qr) return sum[v];
        push(v);
        int m = (l + r) / 2;
        return qsum(2 * v, l, m, ql, qr) + qsum(2 * v + 1, m + 1, r, ql, qr);
    }
    long long qmax(int v, int l, int r, int ql, int qr) {
        if (qr < l || r < ql) return -INF;
        if (ql <= l && r <= qr) return mx1[v];
        push(v);
        int m = (l + r) / 2;
        return max(qmax(2 * v, l, m, ql, qr), qmax(2 * v + 1, m + 1, r, ql, qr));
    }
    long long qmin(int v, int l, int r, int ql, int qr) {
        if (qr < l || r < ql) return INF;
        if (ql <= l && r <= qr) return mn1[v];
        push(v);
        int m = (l + r) / 2;
        return min(qmin(2 * v, l, m, ql, qr), qmin(2 * v + 1, m + 1, r, ql, qr));
    }
    // wygodne wywołania, przedziały [l, r] od 0
    void chmin(int l, int r, long long x) { chmin(1, 0, n - 1, l, r, x); }
    void chmax(int l, int r, long long x) { chmax(1, 0, n - 1, l, r, x); }
    void add(int l, int r, long long x) { add(1, 0, n - 1, l, r, x); }
    long long sumOf(int l, int r) { return qsum(1, 0, n - 1, l, r); }
    long long maxOf(int l, int r) { return qmax(1, 0, n - 1, l, r); }
    long long minOf(int l, int r) { return qmin(1, 0, n - 1, l, r); }
};

// a[i] %= x na przedziale + suma (bez lazy!). Jeśli max < x, nic się nie zmienia → wyjdź.
// Każda skuteczna zmiana co najmniej połowi a[i], więc element zmienia się O(log A) razy.
struct ModTree {
    int n;
    vector<long long> sum, mx;
    ModTree(const vector<long long>& a) : n(a.size()), sum(4 * a.size()), mx(4 * a.size()) { build(1, 0, n - 1, a); }
    void build(int v, int l, int r, const vector<long long>& a) {
        if (l == r) { sum[v] = mx[v] = a[l]; return; }
        int m = (l + r) / 2;
        build(2 * v, l, m, a);
        build(2 * v + 1, m + 1, r, a);
        sum[v] = sum[2 * v] + sum[2 * v + 1];
        mx[v] = max(mx[2 * v], mx[2 * v + 1]);
    }
    void modRange(int v, int l, int r, int ql, int qr, long long x) {
        if (qr < l || r < ql || mx[v] < x) return;          // klucz całej sztuczki
        if (l == r) { sum[v] %= x; mx[v] = sum[v]; return; }
        int m = (l + r) / 2;
        modRange(2 * v, l, m, ql, qr, x);
        modRange(2 * v + 1, m + 1, r, ql, qr, x);
        sum[v] = sum[2 * v] + sum[2 * v + 1];
        mx[v] = max(mx[2 * v], mx[2 * v + 1]);
    }
    long long query(int v, int l, int r, int ql, int qr) {
        if (qr < l || r < ql) return 0;
        if (ql <= l && r <= qr) return sum[v];
        int m = (l + r) / 2;
        return query(2 * v, l, m, ql, qr) + query(2 * v + 1, m + 1, r, ql, qr);
    }
};

