// Wavelet tree na wartościach [lo, hi] (najlepiej po kompresji: 0..σ-1). Przedziały [l, r) od 0.
// Węzeł dzieli wartości na ≤ mid (lewo) i > mid (prawo); b[i] = ile z pierwszych i elementów idzie w lewo.
struct WaveletTree {
    struct Node { int lo, hi, left = -1, right = -1; vector<int> b; };
    vector<Node> t;
    WaveletTree(vector<int> a, int lo, int hi) { build(a.begin(), a.end(), lo, hi); }
    int build(vector<int>::iterator from, vector<int>::iterator to, int lo, int hi) {
        int id = t.size();
        t.push_back({lo, hi});
        if (lo == hi || from == to) return id;
        int mid = lo + (hi - lo) / 2;
        auto goesLeft = [mid](int x) { return x <= mid; };
        vector<int> b(1, 0);
        b.reserve(to - from + 1);
        for (auto it = from; it != to; ++it) b.push_back(b.back() + goesLeft(*it));
        auto pivot = stable_partition(from, to, goesLeft);   // lewa część, potem prawa (kolejność zachowana)
        int L = build(from, pivot, lo, mid);
        int R = build(pivot, to, mid + 1, hi);
        t[id].b = move(b);                                    // t mogło się realokować — używamy indeksów
        t[id].left = L;
        t[id].right = R;
        return id;
    }
    // k-ty najmniejszy (k od 1) w a[l..r)
    int kth(int l, int r, int k) const {
        int v = 0;
        while (t[v].lo != t[v].hi) {
            const vector<int>& b = t[v].b;
            int inLeft = b[r] - b[l];
            if (k <= inLeft) { l = b[l]; r = b[r]; v = t[v].left; }
            else { k -= inLeft; l -= b[l]; r -= b[r]; v = t[v].right; }
        }
        return t[v].lo;
    }
    // ile elementów ≤ x w a[l..r)
    int countLE(int l, int r, int x) const {
        int v = 0, res = 0;
        while (l < r) {
            if (x < t[v].lo) return res;
            if (t[v].hi <= x) return res + (r - l);
            const vector<int>& b = t[v].b;
            int mid = t[v].lo + (t[v].hi - t[v].lo) / 2;
            if (x <= mid) { l = b[l]; r = b[r]; v = t[v].left; }
            else { res += b[r] - b[l]; l -= b[l]; r -= b[r]; v = t[v].right; }
        }
        return res;
    }
};

