int main() {
    // Wejście: n q, a[1..n] (dowolne int), q zapytań (przedziały 1-indeksowane, domknięte):
    // "1 l r k" → k-ty najmniejszy na [l, r];  "2 l r x" → ile elementów ≤ x na [l, r]
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<int> a(n);
    for (auto& x : a) cin >> x;
    vector<int> vals = a;                                 // kompresja → głębokość log n
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    vector<int> c(n);
    for (int i = 0; i < n; i++) c[i] = lower_bound(vals.begin(), vals.end(), a[i]) - vals.begin();
    WaveletTree wt(c, 0, (int)vals.size() - 1);
    while (q--) {
        int type, l, r;
        long long y;
        cin >> type >> l >> r >> y;
        l--;                                              // [l, r] 1-indeksowane → [l-1, r) od 0
        if (type == 1) cout << vals[wt.kth(l, r, (int)y)] << '\n';
        else {
            int idx = upper_bound(vals.begin(), vals.end(), y) - vals.begin() - 1;   // największa wartość ≤ y
            cout << (idx < 0 ? 0 : wt.countLE(l, r, idx)) << '\n';
        }
    }
}

